fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Optional sanity checks in debug mode
    debug_assert_eq!(input.len(), n, "Expected {} rows, got {}", n, input.len());
    for (row_idx, row) in input.iter().enumerate() {
        debug_assert_eq!(
            row.len(),
            m,
            "Row {} has length {}, expected {}",
            row_idx,
            row.len(),
            m
        );
    }
    debug_assert!(j < m, "Column index {} out of bounds (m = {})", j, m);

    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        // We can safely index because of the debug assertions above
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Optional sanity check
    debug_assert_eq!(input.len(), n, "Expected {} rows, got {}", n, input.len());

    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        result.push(get_column(&input, j, m, n));
    }
    result
}

