    #[test]
    fn test_get_column() {
        let mat = vec![
            vec![1, 2, 3],
            vec![4, 5, 6],
            vec![7, 8, 9],
        ];
        assert_eq!(get_column(&mat, 0, 3, 3), vec![1, 4, 7]);
        assert_eq!(get_column(&mat, 1, 3, 3), vec![2, 5, 8]);
        assert_eq!(get_column(&mat, 2, 3, 3), vec![3, 6, 9]);
    }

    #[test]
    fn test_column_stack() {
        let mat = vec![
            vec![1, 2, 3],
            vec![4, 5, 6],
        ];
        let transposed = column_stack(mat, 3, 2);
        // The input is 2×3, so the result should be 3×2:
        // [ [1,4], [2,5], [3,6] ]
        assert_eq!(transposed, vec![
            vec![1, 4],
            vec![2, 5],
            vec![3, 6],
        ]);
    }
